//! Closed Shadow Path: one real personal victory, one enemy deck, top ten only.
use crate::{engine::RuleResult,model::*,rules::*,mystic_contest::ContestOutcome};
use serde::Serialize;
use std::collections::BTreeSet;
pub(crate) const ID:&str="WM027";
pub(crate) const WIN:&str="wm027-win-seal";
const PLAYER:&str="wm027_enemy_deck";
const CARD:&str="wm027_top_ten";
fn same<T:Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).unwrap()==serde_json::to_value(b).unwrap()}
pub(crate) fn definition()->Definition{let mut d=attachment_definition(target(Zone::Society,EntityKind::Any,Relation::ControlledByActor,Range::Anywhere));d.abilities.push(ability(WIN,"赢得隐秘对抗：从一名敌方玩家牌库顶十张中封印一张牌",Timing::Fast,vec![],vec![],vec![Op::WM027Search{contest_id:None}],Some(Event::MysticContestWon)));d}
pub(crate) fn related(a:&AbilitySpec)->bool{a.key.starts_with("wm027-")||a.ops.iter().any(owns)||a.modes.iter().any(|m|m.ops.iter().any(owns))}
fn owns(o:&Op)->bool{match o{Op::WM027Search{..}=>true,Op::ForEachLivingPlayer(v)|Op::ForEachLivingPlayerFromActor(v)=>v.iter().any(owns),Op::IfTargetExhausted{exhausted,ready,..}=>owns(exhausted)||owns(ready),_=>false}}
pub(crate) fn frame_related(f:&ResolutionFrame)->bool{(f.source.card.definition==ID&&f.ability_key!="attach")||f.ability_key.starts_with("wm027-")||f.steps.iter().any(|s|owns(&s.op))}
fn program(id:Option<String>)->AbilitySpec{let mut a=definition().abilities.remove(1);a.ops=vec![Op::WM027Search{contest_id:id}];a}
pub(crate) fn validate_ability(id:&str,a:&AbilitySpec)->RuleResult<()>{let [Op::WM027Search{contest_id}]=a.ops.as_slice()else{return Err("阴影之道触发程序不符".into())};if id!=ID||!same(a,&program(contest_id.clone())){return Err("阴影之道须保留完整原触发".into())}Ok(())}
pub(crate) fn validate_definition(id:&str,d:&Definition)->RuleResult<()>{if id==ID&&!same(d,&definition()){return Err("阴影之道须保留完整结附及获胜触发".into())}Ok(())}
impl Game{
 fn wm027_condition(&self,actor:usize)->bool{self.players.get(actor).is_some_and(|p|!p.eliminated&&(p.society_zone.secrecy>0||self.regions.iter().filter(|r|!r.vacant).flat_map(|r|&r.cards).any(|c|!c.face_down&&c.controller==actor&&crate::catalog::card(&c.definition).kind=="character"&&self.current_subtypes(c).iter().any(|s|s=="吸血鬼"))))}
 pub(crate) fn wm027_observe_win(&mut self,o:&ContestOutcome){let Some(team)=o.winner_team else{return};let sources=self.attachments.iter().filter(|a|a.card.definition==ID&&!a.card.face_down&&self.attachment_host_valid(a)&&self.team(a.card.controller)==team&&o.participants.contains(&a.card.controller)&&self.wm027_condition(a.card.controller)).map(|a|self.source_snapshot(&a.card,None)).collect::<Vec<_>>();for source in sources{self.effects.push_back(Effect::Declare{declaration:Declaration{actor:source.card.controller,source,ability:program(Some(o.contest_id.clone()))}});}}
 fn wm027_source(&self,actor:usize,s:&SourceSnapshot,ops:&[Op])->RuleResult<()>{if actor>=self.players.len()||s.card.definition!=ID||s.card.face_down||s.card.controller!=actor||s.card.owner>=self.players.len()||s.region.is_some()||s.source_region_instance.is_some()||s.play_source.is_some()||s.attachment_host_instance.as_deref()!=Some(format!("society:p{actor}").as_str()){return Err("阴影之道须绑定原操控者及本方秘社".into())}self.mobility_immutable_identity(&s.card)?;let [Op::WM027Search{contest_id:Some(id)}]=ops else{return Err("阴影之道缺少真实隐秘对抗".into())};let o=self.mystic_history.iter().find(|o|o.contest_id==*id).ok_or("阴影之道隐秘记录缺失")?;if o.turn!=self.turn||!o.participants.contains(&actor)||o.winner_team!=Some(self.team(actor)){return Err("阴影之道必须由实际参与获胜的玩家触发".into())}self.validate_mystic_outcome(o)}
 pub(crate) fn validate_wm027_declaration(&self,d:&Declaration)->RuleResult<()>{validate_ability(&d.source.card.definition,&d.ability)?;self.wm027_source(d.actor,&d.source,&d.ability.ops)}
 pub(crate) fn validate_wm027_frame(&self,f:&ResolutionFrame)->RuleResult<()>{let ops=f.steps.iter().map(|s|s.op.clone()).collect::<Vec<_>>();self.wm027_source(f.actor,&f.source,&ops)?;if f.ability_key!=WIN||f.steps.len()!=1||f.steps[0].context!=f.actor||f.cursor>1||!f.targets.is_empty()||f.chosen_region.is_some()||!f.already_paid.is_empty()||(f.cursor==0&&!matches!(f.guard,GuardState::Unchecked))||(f.cursor==1&&!matches!(f.guard,GuardState::Accepted)){return Err("阴影之道原执行帧不符".into())}Ok(())}
 fn wm027_players(&self,actor:usize)->Vec<ChoiceOption>{self.players.iter().filter(|p|!p.eliminated&&self.team(p.seat)!=self.team(actor)).map(|p|ChoiceOption{id:player_id(p.seat),label:p.name.clone(),card:None}).collect()}
 fn wm027_cards(&self,actor:usize,seat:usize)->RuleResult<Vec<ChoiceOption>>{if !self.wm027_players(actor).iter().any(|o|o.id==player_id(seat)){return Err("阴影之道只能检索一名存活敌方玩家".into())}Ok(self.players[seat].deck.iter().take(10).map(|c|self.option(c,actor,None,None)).collect())}
 pub(crate) fn wm027_start(&mut self,f:ResolutionFrame)->RuleResult<()>{self.validate_wm027_frame(&f)?;if !self.wm027_condition(f.actor){return Ok(())}let options=self.wm027_players(f.actor);if options.is_empty(){return Ok(())}self.choice(f.actor,PLAYER,"阴影之道：选择一名敌方玩家".into(),options,1,1,None,ChoiceResolution::Frame{frame:Box::new(f),choice:FrameChoice::WM027Player});self.pending.as_mut().unwrap().choice.allow_decline=Some(false);Ok(())}
 fn wm027_input(&self,f:&ResolutionFrame,chooser:usize,a:&Action)->RuleResult<()>{self.validate_wm027_frame(f)?;if chooser!=f.actor||f.cursor!=1||*a!=(Action{choice_id:a.choice_id.clone(),selected:a.selected.clone(),..Action::new("choose")}){return Err("阴影之道只接受原玩家的真实选择".into())}Ok(())}
 pub(crate) fn wm027_choose_player(&mut self,f:ResolutionFrame,chooser:usize,a:&Action,selected:&[String])->RuleResult<()>{self.wm027_input(&f,chooser,a)?;if selected.len()!=1||!self.wm027_players(f.actor).iter().any(|o|o.id==selected[0]){return Err("阴影之道须选择一名敌方玩家".into())}let seat=self.players.iter().position(|p|player_id(p.seat)==selected[0]).unwrap();let options=self.wm027_cards(f.actor,seat)?;let max=usize::from(!options.is_empty());self.choice(f.actor,CARD,"阴影之道：可从牌库顶十张中封印一张".into(),options,0,max,None,ChoiceResolution::Frame{frame:Box::new(f),choice:FrameChoice::WM027Card{seat}});self.pending.as_mut().unwrap().choice.allow_decline=Some(false);Ok(())}
 pub(crate) fn wm027_choose_card(&mut self,f:&ResolutionFrame,seat:usize,chooser:usize,a:&Action,selected:&[String])->RuleResult<()>{self.wm027_input(f,chooser,a)?;let options=self.wm027_cards(f.actor,seat)?;if selected.len()>1||selected.first().is_some_and(|id|!options.iter().any(|o|&o.id==id)){return Err("阴影之道至多封印原敌方牌库顶十张中的一张".into())}if let Some(id)=selected.first(){let index=self.players[seat].deck.iter().position(|c|&c.id==id).unwrap();let c=&self.players[seat].deck[index];let host=format!("society:p{}",c.owner);if !self.seal_host_valid(&host){return Err("阴影之道封印牌原拥有者秘社已失效".into())}let c=self.players[seat].deck.remove(index);self.seal_card_on_valid_host(c,f.actor,&host);}self.shuffle_player(seat);Ok(())}
 pub(crate) fn validate_wm027_state(&self)->RuleResult<()>{let mut seen=BTreeSet::new();let mut remember=|s:&SourceSnapshot,ops:&[Op]|->RuleResult<()>{if let [Op::WM027Search{contest_id:Some(id)}]=ops{if !seen.insert((s.card.id.clone(),id.clone())){return Err("阴影之道重复处理同一次获胜".into())}}Ok(())};for i in &self.stack{if let Some(f)=&i.frame{if frame_related(f){self.validate_wm027_frame(f)?;remember(&f.source,&f.steps.iter().map(|s|s.op.clone()).collect::<Vec<_>>())?;}}}for e in &self.effects{match e{Effect::Declare{declaration:d}if related(&d.ability)=>{self.validate_wm027_declaration(d)?;remember(&d.source,&d.ability.ops)?;},Effect::Frame{frame:f}if frame_related(f)=>{self.validate_wm027_frame(f)?;remember(&f.source,&f.steps.iter().map(|s|s.op.clone()).collect::<Vec<_>>())?;},_=>()}}
 if let Some(p)=&self.pending{match &p.resolution{ChoiceResolution::Declare{declaration:d,..}if related(&d.ability)=>{self.validate_wm027_declaration(d)?;remember(&d.source,&d.ability.ops)?;},ChoiceResolution::Frame{frame:f,choice}if frame_related(f)||matches!(choice,FrameChoice::WM027Player|FrameChoice::WM027Card{..})=>{self.validate_wm027_frame(f)?;remember(&f.source,&f.steps.iter().map(|s|s.op.clone()).collect::<Vec<_>>())?;let(kind,title,options,min,max)=match choice{FrameChoice::WM027Player=>(PLAYER,"阴影之道：选择一名敌方玩家",self.wm027_players(f.actor),1,1),FrameChoice::WM027Card{seat}=>{let v=self.wm027_cards(f.actor,*seat)?;let n=usize::from(!v.is_empty());(CARD,"阴影之道：可从牌库顶十张中封印一张",v,0,n)},_=>return Err("阴影之道待选程序错配".into())};if f.cursor!=1||p.seat!=f.actor||p.choice.player_id!=player_id(f.actor)||p.choice.kind!=kind||p.choice.title!=title||p.choice.min!=Some(min)||p.choice.max!=Some(max)||p.choice.allow_decline!=Some(false)||!p.choice.preview_cards.is_empty()||!same(&p.choice.options,&options){return Err("阴影之道待选须与真实敌方顶十张一致".into())}},_=>{if p.choice.kind==PLAYER||p.choice.kind==CARD{return Err("阴影之道待选来源缺失".into())}}}}Ok(())}
}
